const failure = $input.first().json;
const execution = failure.execution || {};
const error = execution.error || failure.error || {};
return [{ json: {
  workflow: failure.workflow?.name ?? "unknown",
  executionId: execution.id ?? null,
  error: error.message ?? String(error),
  failedNode: execution.lastNodeExecuted ?? null,
  at: new Date().toISOString()
} }];
